/**
 * Unit tests for lib/shell-cwd.ts (#3411).
 *
 * The parser decides whether a security verdict is judged against the right
 * directory, so the cases that matter most are the ones where it must REFUSE
 * to guess: a quoted `cd`, a subshell `cd`, and `pushd`. Getting those wrong
 * in the permissive direction would let a stale directory speak for the shell
 * and turn a protected-branch push into an allow.
 */

import { describe, it, expect } from 'vitest';
import { extractPersistentCd, applyCwdEffect } from '../../lib/shell-cwd.js';

describe('extractPersistentCd', () => {
  it('reports unchanged for a command with no cd', () => {
    expect(extractPersistentCd('git status')).toEqual({ kind: 'unchanged' });
    expect(extractPersistentCd('npm test && echo done')).toEqual({ kind: 'unchanged' });
  });

  it('captures a single absolute cd', () => {
    expect(extractPersistentCd('cd /a/b')).toEqual({ kind: 'set', targets: ['/a/b'] });
  });

  it('captures a cd at the head of a chain', () => {
    expect(extractPersistentCd('cd /a/b && git status')).toEqual({
      kind: 'set',
      targets: ['/a/b'],
    });
  });

  it('captures every top-level cd in order so relative ones can compound', () => {
    expect(extractPersistentCd('cd a && cd b')).toEqual({
      kind: 'set',
      targets: ['a', 'b'],
    });
  });

  it('accepts `;` as a separator, not just `&&`', () => {
    expect(extractPersistentCd('cd /a; git status')).toEqual({
      kind: 'set',
      targets: ['/a'],
    });
  });

  // ---------------------------------------------------------------------------
  // The cases where guessing would be a security bug
  // ---------------------------------------------------------------------------

  it('does NOT record a cd inside sh -c: the parent shell never moves', () => {
    expect(extractPersistentCd(`sh -c 'cd /a/b && git push'`)).toEqual({
      kind: 'unchanged',
    });
  });

  it('does NOT record a cd inside a subshell: scoped to the child', () => {
    expect(extractPersistentCd('(cd /a/b && git push)')).toEqual({ kind: 'unchanged' });
  });

  it('keeps a top-level cd but ignores a later quoted one', () => {
    expect(extractPersistentCd(`cd /a && sh -c 'cd /b && pwd'`)).toEqual({
      kind: 'set',
      targets: ['/a'],
    });
  });

  it('reports unknown for forms it cannot model rather than guessing', () => {
    expect(extractPersistentCd('cd')).toEqual({ kind: 'unknown' });
    expect(extractPersistentCd('cd -')).toEqual({ kind: 'unknown' });
    expect(extractPersistentCd('pushd /a')).toEqual({ kind: 'unknown' });
    expect(extractPersistentCd('popd')).toEqual({ kind: 'unknown' });
    expect(extractPersistentCd('cd --')).toEqual({ kind: 'unknown' });
  });

  it('stops at a pipe', () => {
    expect(extractPersistentCd('cd /a | tee log')).toEqual({
      kind: 'set',
      targets: ['/a'],
    });
  });
});

describe('applyCwdEffect', () => {
  const PROJECT = '/proj';

  it('leaves the current value alone when unchanged', () => {
    expect(applyCwdEffect('/proj/wt', { kind: 'unchanged' }, PROJECT)).toBe('/proj/wt');
  });

  it('returns null for unknown so callers drop the record', () => {
    expect(applyCwdEffect('/proj/wt', { kind: 'unknown' }, PROJECT)).toBeNull();
  });

  it('replaces on an absolute target', () => {
    expect(applyCwdEffect('/proj/wt', { kind: 'set', targets: ['/other'] }, PROJECT)).toBe(
      '/other',
    );
  });

  it('resolves a relative target against the project dir when nothing is known', () => {
    expect(applyCwdEffect(null, { kind: 'set', targets: ['.worktrees/x'] }, PROJECT)).toBe(
      '/proj/.worktrees/x',
    );
  });

  it('resolves a relative target against the KNOWN cwd, not the project dir', () => {
    expect(applyCwdEffect('/proj/a', { kind: 'set', targets: ['b'] }, PROJECT)).toBe(
      '/proj/a/b',
    );
  });

  it('compounds successive relative targets like bash does', () => {
    expect(applyCwdEffect(null, { kind: 'set', targets: ['a', 'b'] }, PROJECT)).toBe(
      '/proj/a/b',
    );
  });

  it('normalises .. so a cd out of a worktree is not mistaken for staying in', () => {
    expect(applyCwdEffect('/proj/.worktrees/x', { kind: 'set', targets: ['../..'] }, PROJECT)).toBe(
      '/proj',
    );
  });
});
